   %m_utl_hash_define(
      table = WORK.class
    , creds = %str(encryptkey=aespasskey)
    , name  = class
    , keys  = Name
    , cols  = _ALL_
    , debug = Y
      );
   rc = class.output(dataset: 'WORK.result');
run;

proc print data=WORK.result noobs;
   title 'Example 2: Create a hash object from an encrypted SAS dataset';
run; title ;
```

