    , name      = classfit
    , keys      = Name
    , ordered   = Y
    , debug     = Y
      );
   rc = hclass.first();
   do while (rc eq 0);
      if Sex eq 'F' then do;
         rc = classfit.find();
         output;
      end;
      rc = hclass.next();
   end;
run;

