 , intype = TBL
 , inhost =
 , prmenv = PARAM_ENV
 , prmvar = PARAM_NAME
 , prmval = PARAM_VALUE
 , prmtyp = PARAM_TYPE
 , prmtxt = PARAM_TEXT
 , prmflg = MACRO_FLG
 , debug  = N
   );
